/**
 * Reference media for each room, resolved at build time.
 *
 * 1. `public/data/references-gallery.json` – generated by
 *    scripts/build-cloudinary-gallery.mjs from the Cloudinary folders merged
 *    with the CMS metadata (same approach as anewstyle.cz).
 * 2. Otherwise the CMS list itself (`room.images`), transformed on the fly.
 * 3. Rooms with neither fall back to the Cloudinary tag list at runtime
 *    (handled in src/pages/projekty.astro).
 */
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import type { ReferenceRoom } from "@/data/site";
import { cloudinaryImage, cloudinarySrcset } from "@/lib/cloudinary";

export interface GalleryItem {
  type: "image" | "video";
  alt: string;
  thumb: string;
  thumbSrcset?: string;
  full: string;
  poster?: string;
  uploadedAt?: string;
  width: number;
  height: number;
  fullWidth?: number;
  fullHeight?: number;
  orientation?: "landscape" | "portrait";
}

interface GalleryJson {
  generatedAt: string | null;
  rooms: Record<string, GalleryItem[]>;
}

const FILE = resolve(process.cwd(), "public/data/references-gallery.json");
const TILE_WIDTHS = [360, 540, 800, 1080];
const RATIO = 4 / 3;

let cache: GalleryJson | undefined;
function generated(): GalleryJson {
  if (cache) return cache;
  try {
    cache = existsSync(FILE)
      ? (JSON.parse(readFileSync(FILE, "utf8")) as GalleryJson)
      : { generatedAt: null, rooms: {} };
  } catch {
    cache = { generatedAt: null, rooms: {} };
  }
  return cache;
}

const isVideo = (src: string) => /\/video\/upload\//.test(src) || /\.(mp4|webm|mov)(\?|$)/i.test(src);

/** Same transforms as the build script, computed from the CMS URL alone. */
function fromCms(room: ReferenceRoom): GalleryItem[] {
  return room.images
    .filter((image) => image.src && !image.hidden)
    .map((image, index) => {
      const alt = image.alt?.trim() || `${room.title} — reference ${index + 1}`;
      if (isVideo(image.src)) {
        const poster = image.src.replace(/\.(mp4|webm|mov)$/i, "").concat(".jpg");
        return { type: "video", alt, thumb: poster, full: image.src, poster, width: 800, height: 600 };
      }
      return {
        type: "image",
        alt,
        thumb: cloudinaryImage(image.src, { width: 800, height: 600, fit: "fill" }),
        thumbSrcset: cloudinarySrcset(image.src, TILE_WIDTHS, { ratio: RATIO, fit: "fill" }),
        full: cloudinaryImage(image.src, { width: 2000, fit: "limit" }),
        width: 800,
        height: 600,
      };
    });
}

export function getRoomMedia(room: ReferenceRoom): GalleryItem[] {
  const fromCloudinary = generated().rooms[room.slug];
  if (fromCloudinary?.length) return fromCloudinary;
  return fromCms(room);
}

export const galleryGeneratedAt = () => generated().generatedAt;
